import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { TransacaoService, Transacao } from '../../services/transacao.service';

// ========================================================================
// COMPONENTE
// ========================================================================

@Component({
  selector: 'app-transacoes',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './transacoes.component.html',
  styleUrls: ['./transacoes.component.scss']
})
export class TransacoesComponent implements OnInit {
  // ====================================================================
  // ESTADO
  // ====================================================================

  transacoes: Transacao[] = [];
  mostrarForm = false;
  isLoading = false;
  isSaving = false;
  hasError = false;
  errorMessage = '';
  editandoId: number | null = null;

  transacaoForm: FormGroup;

  // Categorias fixas para o select (você pode obter da API se preferir)
  categorias = [
    { id: 1, nome: 'Alimentação' },
    { id: 2, nome: 'Transporte' },
    { id: 3, nome: 'Saúde' },
    { id: 4, nome: 'Entretenimento' },
    { id: 5, nome: 'Educação' },
    { id: 6, nome: 'Utilidades' },
    { id: 7, nome: 'Salário' },
    { id: 8, nome: 'Investimentos' },
    { id: 9, nome: 'Outros' }
  ];

  // ====================================================================
  // CONSTRUTOR
  // ====================================================================

  constructor(
    private transacaoService: TransacaoService,
    private fb: FormBuilder
  ) {
    this.transacaoForm = this.criarFormulario();
  }

  // ====================================================================
  // LIFECYCLE
  // ====================================================================

  ngOnInit(): void {
    this.carregarTransacoes();
  }

  // ====================================================================
  // MÉTODOS PRIVADOS
  // ====================================================================

  /**
   * Cria um novo FormGroup para o formulário de transações
   */
  private criarFormulario(): FormGroup {
    return this.fb.group({
      categoria_id: ['', [Validators.required]],
      valor: ['', [Validators.required, Validators.min(0.01)]],
      tipo: ['receita', [Validators.required]],
      data: ['', [Validators.required]],
      descricao: ['', [Validators.required, Validators.minLength(3)]]
    });
  }

  /**
   * Reseta o formulário aos valores padrão
   */
  private resetarFormulario(): void {
    this.transacaoForm.reset({
      categoria_id: '',
      valor: '',
      tipo: 'receita',
      data: this.obterDataAtual(),
      descricao: ''
    });
    this.editandoId = null;
  }

  /**
   * Obtém a data atual no formato YYYY-MM-DD
   */
  private obterDataAtual(): string {
    const hoje = new Date();
    return hoje.toISOString().split('T')[0];
  }

  /**
   * Formata o valor para moeda
   */
  private formatarMoeda(valor: number): string {
    return new Intl.NumberFormat('pt-PT', {
      style: 'currency',
      currency: 'EUR'
    }).format(valor);
  }

  // ====================================================================
  // MÉTODOS PÚBLICOS - CARREGAMENTO
  // ====================================================================

  /**
   * Carrega a lista de transações da API
   */
  carregarTransacoes(): void {
    this.isLoading = true;
    this.hasError = false;

    this.transacaoService.listar().subscribe({
      next: (response) => {
        if (response.success && response.data) {
          const data = response.data as Transacao[];
          this.transacoes = Array.isArray(data) ? data : [data];
        } else {
          this.transacoes = [];
        }
        this.isLoading = false;
      },
      error: (error) => {
        console.error('Erro ao carregar transações:', error);
        this.hasError = true;
        this.errorMessage = 'Erro ao carregar as transações. Tente novamente.';
        this.isLoading = false;
      }
    });
  }

  // ====================================================================
  // MÉTODOS PÚBLICOS - FORMULÁRIO
  // ====================================================================

  /**
   * Alterna a visibilidade do formulário
   */
  toggleFormulario(): void {
    this.mostrarForm = !this.mostrarForm;
    if (!this.mostrarForm) {
      this.resetarFormulario();
    } else {
      // Define a data atual quando abre o formulário
      this.transacaoForm.patchValue({
        data: this.obterDataAtual()
      });
    }
  }

  /**
   * Abre o formulário para editar uma transação
   */
  editar(transacao: Transacao): void {
    this.editandoId = transacao.id || null;
    this.transacaoForm.patchValue({
      categoria_id: transacao.categoria_id,
      valor: transacao.valor,
      tipo: transacao.tipo,
      data: transacao.data,
      descricao: transacao.descricao
    });
    this.mostrarForm = true;
  }

  /**
   * Cancela a edição/criação e fecha o formulário
   */
  cancelar(): void {
    this.mostrarForm = false;
    this.resetarFormulario();
  }

  /**
   * Salva a transação (cria ou atualiza)
   */
  salvar(): void {
    if (!this.transacaoForm.valid) {
      this.errorMessage = 'Por favor, preencha todos os campos corretamente.';
      return;
    }

    this.isSaving = true;
    const formValue = this.transacaoForm.value;

    if (this.editandoId) {
      // Atualizar transação existente
      this.transacaoService.atualizar(this.editandoId, formValue).subscribe({
        next: () => {
          this.carregarTransacoes();
          this.cancelar();
          this.isSaving = false;
        },
        error: (error) => {
          console.error('Erro ao atualizar transação:', error);
          this.errorMessage = 'Erro ao atualizar a transação. Tente novamente.';
          this.isSaving = false;
        }
      });
    } else {
      // Criar nova transação
      this.transacaoService.criar(formValue).subscribe({
        next: () => {
          this.carregarTransacoes();
          this.cancelar();
          this.isSaving = false;
        },
        error: (error) => {
          console.error('Erro ao criar transação:', error);
          this.errorMessage = 'Erro ao criar a transação. Tente novamente.';
          this.isSaving = false;
        }
      });
    }
  }

  /**
   * Remove uma transação
   */
  deletar(transacao: Transacao): void {
    if (!transacao.id) return;

    if (confirm(`Tem a certeza que deseja eliminar esta transação (${this.formatarMoeda(transacao.valor)})?`)) {
      this.transacaoService.remover(transacao.id).subscribe({
        next: () => {
          this.carregarTransacoes();
        },
        error: (error) => {
          console.error('Erro ao deletar transação:', error);
          this.errorMessage = 'Erro ao eliminar a transação. Tente novamente.';
        }
      });
    }
  }

  /**
   * Retorna o nome da categoria pelo ID
   */
  obterNomeCategoria(categoriaId: number): string {
    return this.categorias.find(c => c.id === categoriaId)?.nome || 'Desconhecido';
  }

  /**
   * Formata valor para exibição
   */
  formatarValor(valor: number): string {
    return this.formatarMoeda(valor);
  }

  /**
   * Formata data para exibição (DD/MM/YYYY)
   */
  formatarData(data: string): string {
    const date = new Date(data + 'T00:00:00');
    return new Intl.DateTimeFormat('pt-PT').format(date);
  }

  /**
   * Verifica se está em modo edição
   */
  isEditando(): boolean {
    return this.editandoId !== null;
  }

  /**
   * Retorna o título do formulário
   */
  getTituloFormulario(): string {
    return this.editandoId ? 'Editar Transação' : 'Nova Transação';
  }

  /**
   * Retorna o texto do botão de salvar
   */
  getTextoBotaoSalvar(): string {
    return this.editandoId ? 'Atualizar' : 'Criar';
  }
}
<div class="transacoes-container">
  <div class="transacoes-header">
    <div>
      <h2>Transacoes</h2>
      <p>Seu extrato financeiro em tempo real</p>
    </div>

    <button
      class="btn-primary"
      (click)="toggleFormulario()"
      [disabled]="isLoading">
      <span *ngIf="!mostrarForm">+ Nova Transacao</span>
      <span *ngIf="mostrarForm">Fechar</span>
    </button>
  </div>

  <div *ngIf="hasError" class="alert-error">
    <strong>Erro:</strong> {{ errorMessage }}
    <button class="alert-close" (click)="hasError = false">X</button>
  </div>

  <div *ngIf="isLoading" class="loading-container">
    <div class="spinner"></div>
    <p>Carregando transacoes...</p>
  </div>

  <div *ngIf="!isLoading && transacoes.length === 0 && !mostrarForm" class="empty-state">
    <div class="empty-icon">💳</div>
    <h3>Nenhuma transacao registada</h3>
    <p>Crie a sua primeira movimentacao com o botao acima.</p>
  </div>

  <section *ngIf="!isLoading && transacoes.length > 0 && !mostrarForm" class="extrato-lista">
    <article class="extrato-item" *ngFor="let t of transacoes" [class.tipo-receita]="t.tipo === 'receita'" [class.tipo-despesa]="t.tipo === 'despesa'">
      <div class="item-left">
        <div class="tipo-indicador" [class.receita]="t.tipo === 'receita'" [class.despesa]="t.tipo === 'despesa'">
          <span *ngIf="t.tipo === 'receita'">↗</span>
          <span *ngIf="t.tipo === 'despesa'">↘</span>
        </div>

        <div class="item-info">
          <strong>{{ t.descricao }}</strong>
          <div class="item-subinfo">
            <span>{{ formatarData(t.data) }}</span>
            <span class="dot">•</span>
            <span>{{ obterNomeCategoria(t.categoria_id) }}</span>
          </div>
        </div>
      </div>

      <div class="item-right">
        <div class="valor" [class.receita]="t.tipo === 'receita'" [class.despesa]="t.tipo === 'despesa'">
          {{ t.tipo === 'receita' ? '+' : '-' }} {{ formatarValor(t.valor) }}
        </div>

        <div class="item-actions">
          <button class="icon-btn" (click)="editar(t)" title="Editar">✏️</button>
          <button class="icon-btn danger" (click)="deletar(t)" title="Apagar">🗑️</button>
        </div>
      </div>
    </article>
  </section>

  <div class="modal-backdrop" *ngIf="mostrarForm" (click)="cancelar()">
    <div class="modal-card" (click)="$event.stopPropagation()">
      <div class="modal-header">
        <h3>{{ getTituloFormulario() }}</h3>
        <button type="button" class="icon-btn" (click)="cancelar()">X</button>
      </div>

      <form [formGroup]="transacaoForm" (ngSubmit)="salvar()" class="transacao-form">
        <div class="form-group">
          <label for="categoria_id">Categoria</label>
          <select id="categoria_id" formControlName="categoria_id" class="form-control">
            <option value="">Selecione uma categoria</option>
            <option *ngFor="let cat of categorias" [value]="cat.id">{{ cat.nome }}</option>
          </select>
        </div>

        <div class="form-group">
          <label>Tipo</label>
          <div class="tipo-options">
            <label class="pill-option receita">
              <input type="radio" value="receita" formControlName="tipo" /> Receita
            </label>
            <label class="pill-option despesa">
              <input type="radio" value="despesa" formControlName="tipo" /> Despesa
            </label>
          </div>
        </div>

        <div class="form-grid">
          <div class="form-group">
            <label for="valor">Valor (€)</label>
            <input id="valor" type="number" formControlName="valor" step="0.01" min="0" class="form-control" placeholder="0.00" />
          </div>

          <div class="form-group">
            <label for="data">Data</label>
            <input id="data" type="date" formControlName="data" class="form-control" />
          </div>
        </div>

        <div class="form-group">
          <label for="descricao">Descricao</label>
          <textarea id="descricao" formControlName="descricao" rows="3" class="form-control" placeholder="Descricao da movimentacao"></textarea>
        </div>

        <div class="form-actions">
          <button type="button" class="btn-secondary" (click)="cancelar()" [disabled]="isSaving">Cancelar</button>
          <button type="submit" class="btn-primary" [disabled]="!transacaoForm.valid || isSaving">
            <span *ngIf="!isSaving">{{ getTextoBotaoSalvar() }}</span>
            <span *ngIf="isSaving">Guardando...</span>
          </button>
        </div>
      </form>
    </div>
  </div>
</div>
